  },
  {
    id: "canzuk",
    label: "CANZUK (mostly deficit)",
    sharePct: 3,
    litersM: 2.8,
    confidence: "carried",
    compensated: false,
  },
  {
    id: "row",
    label: "Rest of world",
    sharePct: 7,
    litersM: 6.4,
    confidence: "carried",
    compensated: false,
  },
];

/** Time series: US liters + estimated global share */
export const COLLECTION_PATH: {
  year: number;
  usLitersM: number;
  worldLitersM: number;
  usSharePct: number;
  usCenters: number;
  confidence: Confidence;
}[] = [
  { year: 2017, usLitersM: 42, worldLitersM: 62, usSharePct: 68, usCenters: 680, confidence: "carried" },
  { year: 2018, usLitersM: 48, worldLitersM: 68, usSharePct: 71, usCenters: 750, confidence: "carried" },
  { year: 2019, usLitersM: 53, worldLitersM: 69, usSharePct: 77, usCenters: 850, confidence: "estimated" },
  { year: 2020, usLitersM: 45, worldLitersM: 59, usSharePct: 76, usCenters: 950, confidence: "estimated" },
  { year: 2021, usLitersM: 49, worldLitersM: 68, usSharePct: 72, usCenters: 1050, confidence: "estimated" },
  { year: 2022, usLitersM: 53, worldLitersM: 76, usSharePct: 70, usCenters: 1120, confidence: "estimated" },
  { year: 2023, usLitersM: 56, worldLitersM: 82, usSharePct: 68, usCenters: 1180, confidence: "estimated" },
  { year: 2024, usLitersM: 57.6, worldLitersM: 86, usSharePct: 67, usCenters: 1210, confidence: "estimated" },
  { year: 2025, usLitersM: 62.5, worldLitersM: 92, usSharePct: 68, usCenters: 1247, confidence: "estimated" },
];

/** EU plasma for PDMP manufacturing ??? origin mix */
export const EU_ORIGIN_MIX: {
  id: string;
  label: string;
  sharePct: number;
  note: string;
}[] = [
  {
    id: "eu4",
    label: "EU-4 compensated collectors",
    sharePct: 38,
    note: "Germany, Austria, Czechia, Hungary ??? commercial plasmapheresis",
  },
  {
    id: "us",
    label: "United States imports",
    sharePct: 38,
    note: "Source plasma / intermediates entering EU fractionation or finished PDMP",
  },
  {
    id: "eu_other",
    label: "Other EU domestic (mostly VNRD)",
    sharePct: 24,
    note: "23 Member States without commercial compensated collections",
  },
];

/** Collection intensity ??? liters per 1,000 residents (anchor years ~2017???2019, carried) */
export const INTENSITY_ROWS: {
  id: string;
  label: string;
  litersPer1k: number;
  compensated: boolean;
  region: "US" | "EU" | "Other";
  confidence: Confidence;
}[] = [
  { id: "us", label: "United States", litersPer1k: 163, compensated: true, region: "US", confidence: "disclosed" },
  { id: "cz", label: "Czechia", litersPer1k: 65, compensated: true, region: "EU", confidence: "disclosed" },
  { id: "de", label: "Germany", litersPer1k: 40, compensated: true, region: "EU", confidence: "disclosed" },
  { id: "at", label: "Austria", litersPer1k: 38, compensated: true, region: "EU", confidence: "estimated" },
  { id: "hu", label: "Hungary", litersPer1k: 35, compensated: true, region: "EU", confidence: "estimated" },
  { id: "au", label: "Australia", litersPer1k: 29, compensated: false, region: "Other", confidence: "disclosed" },
  { id: "nl", label: "Netherlands", litersPer1k: 18, compensated: false, region: "EU", confidence: "disclosed" },
  { id: "nz", label: "New Zealand", litersPer1k: 14, compensated: false, region: "Other", confidence: "disclosed" },
  { id: "ca", label: "Canada", litersPer1k: 10.3, compensated: false, region: "Other", confidence: "estimated" },
  { id: "uk", label: "United Kingdom", litersPer1k: 2, compensated: false, region: "Other", confidence: "carried" },
];

/** Self-reliance vs import dependence (immunoglobulin / PDMP feedstock framing) */
export const DEPENDENCY_ROWS: {
  id: string;
  label: string;
  selfReliancePct: number;
  usImportPct: number;
  patientsNote: string;
}[] = [
  { id: "us", label: "United States", selfReliancePct: 100, usImportPct: 0, patientsNote: "Net exporter of plasma for fractionation" },
  { id: "de", label: "Germany", selfReliancePct: 85, usImportPct: 8, patientsNote: "EU-4 surplus contributor" },
  { id: "au", label: "Australia", selfReliancePct: 55, usImportPct: 40, patientsNote: "Strong VNRD; still imports" },
  { id: "fr", label: "France", selfReliancePct: 50, usImportPct: 35, patientsNote: "Public model; structural gap" },
  { id: "it", label: "Italy", selfReliancePct: 45, usImportPct: 40, patientsNote: "Recovered + source mix" },
  { id: "es", label: "Spain", selfReliancePct: 40, usImportPct: 45, patientsNote: "Rising Ig demand" },
  { id: "ca", label: "Canada", selfReliancePct: 20, usImportPct: 80, patientsNote: "CBS target ~30% Ig sufficiency" },
  { id: "uk", label: "United Kingdom", selfReliancePct: 5, usImportPct: 90, patientsNote: "Post-vCJD fractionation restart limited" },
];

/** Scatter: centers (proxy capacity) vs collection intensity */
export const CAPACITY_SCATTER: {
  id: string;
  label: string;
  centers: number;
  litersPer1k: number;
  shareOfGlobalPct: number;
  compensated: boolean;
}[] = [
  { id: "us", label: "United States", centers: 1247, litersPer1k: 163, shareOfGlobalPct: 68, compensated: true },
  { id: "eu4", label: "EU-4 commercial", centers: 190, litersPer1k: 45, shareOfGlobalPct: 9, compensated: true },
  { id: "cn", label: "China", centers: 120, litersPer1k: 5, shareOfGlobalPct: 8, compensated: false },
  { id: "au", label: "Australia", centers: 45, litersPer1k: 29, shareOfGlobalPct: 1.2, compensated: false },
  { id: "ca", label: "Canada", centers: 25, litersPer1k: 10, shareOfGlobalPct: 0.8, compensated: false },
  { id: "uk", label: "United Kingdom", centers: 8, litersPer1k: 2, shareOfGlobalPct: 0.2, compensated: false },
];

/** EU deficit path ??? liters short of Ig self-sufficiency framing */
export const EU_DEFICIT_PATH: {
  year: number;
  deficitML: number;
  usCoverSharePct: number;
}[] = [
  { year: 2011, deficitML: -0.5, usCoverSharePct: 5 },
  { year: 2014, deficitML: 1.2, usCoverSharePct: 16 },
  { year: 2017, deficitML: 2.4, usCoverSharePct: 24 },
  { year: 2019, deficitML: 3.5, usCoverSharePct: 35 },
  { year: 2021, deficitML: 3.8, usCoverSharePct: 38 },
  { year: 2023, deficitML: 4.0, usCoverSharePct: 38 },
  { year: 2025, deficitML: 4.2, usCoverSharePct: 38 },
];

/** Reference table for prose */
export const REFERENCE_TABLE: {
  metric: string;
  value: string;
  source: string;
}[] = [
  { metric: "US share of global source plasma (2025 desk)", value: "~68%", source: "Jaworski / MRB synthesis" },
  { metric: "US source plasma collected (2025)", value: "62.5 million L", source: "Industry center/liter tally" },
  { metric: "FDA-licensed US plasma centers (end-2025)", value: "1,247", source: "Center registry roll-up" },
  { metric: "EU PDMP feedstock from US plasma", value: "~38%", source: "PPTA" },
  { metric: "EU-4 commercial share of EU PDMP plasma", value: "~38%", source: "Niskanen / PPTA framing" },
  { metric: "Other EU domestic share of EU PDMP plasma", value: "~24%", source: "Niskanen / PPTA framing" },
  { metric: "EU structural deficit (approx.)", value: "3.8???5 million L", source: "Vox Sanguinis / EDQM" },
  { metric: "US collection rate (2019)", value: "163 L / 1,000 residents", source: "EDQM / Jaworski" },
  { metric: "Compensating five countries' global therapy plasma", value: "~90%", source: "Niskanen Center" },
  { metric: "2020 world collection dip vs 2019", value: "???14.5%", source: "MRB / Hotchko IPFA" },
];

export function fmtPct(n: number, digits = 0): string {
  return `${n.toFixed(digits)}%`;
}

export function fmtLitersM(n: number, digits = 1): string {
  return `${n.toFixed(digits)}M L`;
}

export function regionPie() {
  return REGION_SHARES.map((r) => ({
    name: r.label,
    value: r.sharePct,
    litersM: r.litersM,
    compensated: r.compensated,
  }));
}

export function euOriginPie() {
  return EU_ORIGIN_MIX.map((r) => ({
    name: r.label,
    value: r.sharePct,
  }));
}

export function intensityBars(filter: "all" | "EU" | "compensated" | "vnr") {
  return INTENSITY_ROWS.filter((r) => {
    if (filter === "all") return true;
    if (filter === "EU") return r.region === "EU" || r.id === "us";
    if (filter === "compensated") return r.compensated;
    return !r.compensated;
  }).map((r) => ({
    name: r.label,
    litersPer1k: r.litersPer1k,
    compensated: r.compensated,
    fill: r.compensated ? "#0f766e" : "#64748b",
  }));
}

export function dependencyScatter() {
  return DEPENDENCY_ROWS.map((r) => ({
    name: r.label,
    x: r.selfReliancePct,
    y: r.usImportPct,
    z: Math.max(8, 100 - r.selfReliancePct),
  }));
}

export function collectionComposed() {
  return COLLECTION_PATH.map((r) => ({
    year: String(r.year),
    usLitersM: r.usLitersM,
    worldLitersM: r.worldLitersM,
    usSharePct: r.usSharePct,
    usCenters: r.usCenters,
  }));
}

export function euDeficitSeries() {
  return EU_DEFICIT_PATH.map((r) => ({
    year: String(r.year),
    deficitML: r.deficitML,
    usCoverSharePct: r.usCoverSharePct,
  }));
}

/** Analytical HHI on regional share buckets */
export function regionHhi(): number {
  return Math.round(
    REGION_SHARES.reduce((s, r) => s + r.sharePct * r.sharePct, 0),
  );
}

args.streamContent:
"use client";

import { useMemo, useState } from "react";
import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  CAPACITY_SCATTER,
  HEADLINE,
  SOURCE_NOTE,
  collectionComposed,
  dependencyScatter,
  euDeficitSeries,
  euOriginPie,
  fmtLitersM,
  fmtPct,
  intensityBars,
  regionHhi,
  regionPie,
} from "@/data/us-share-of-global-source-plasma-2026-data";

// viz-types: region donut, EU origin pie, collection area+line compose, intensity bars, dependency scatter, deficit area, capacity bubble | layout: default

type ViewId = "global" | "eu" | "intensity" | "capacity";
type IntensityFilter = "all" | "EU" | "compensated" | "vnr";
type PathMetric = "liters" | "share" | "centers";

const US = "#0f766e";
const EU = "#0369a1";
const MUTED = "#94a3b8";
const WARN = "#b45309";
const PIE_COLORS = ["#0f766e", "#0369a1", "#64748b", "#7c3aed", "#b45309", "#be123c"];

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function UsShareOfGlobalSourcePlasma2026Dashboard() {
  const [view, setView] = useState<ViewId>("global");
  const [intensityFilter, setIntensityFilter] =
    useState<IntensityFilter>("all");
  const [pathMetric, setPathMetric] = useState<PathMetric>("liters");
  const [showWorld, setShowWorld] = useState(true);

  const regions = useMemo(() => regionPie(), []);
  const euOrigin = useMemo(() => euOriginPie(), []);
  const path = useMemo(() => collectionComposed(), []);
  const intensity = useMemo(
    () => intensityBars(intensityFilter),
    [intensityFilter],
  );
  const dependency = useMemo(() => dependencyScatter(), []);
  const deficit = useMemo(() => euDeficitSeries(), []);
  const hhi = useMemo(() => regionHhi(), []);

  return (
    <div
      className="space-y-6"
      data-viz="us-share-of-global-source-plasma-2026"
    >
      <div className="rounded-xl border border-slate-200 bg-gradient-to-br from-slate-900 via-teal-950 to-slate-900 px-5 py-5 text-white shadow-sm sm:px-6">
        <p className="text-xs font-semibold uppercase tracking-wider text-teal-300">
          Source plasma ?? fractionation feedstock
        </p>
        <h2 className="mt-1 text-xl font-bold tracking-tight sm:text-2xl">
          US collects ~{fmtPct(HEADLINE.usGlobalSharePct, 0)} of global source
          plasma
        </h2>
        <p className="mt-2 max-w-3xl text-sm leading-relaxed text-slate-300">
          Roughly {fmtLitersM(HEADLINE.usLiters2025M)} of US source plasma in
          2025 sits inside a ~{fmtLitersM(HEADLINE.worldLiters2025M, 0)} world
          pool. EU PDMP manufacturing still draws ~{fmtPct(HEADLINE.euUsImportSharePct, 0)}{" "}
          of its plasma from US donors ??? the same share as the entire EU-4
          commercial bloc.
        </p>
        <div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-4">
          {[
            {
              label: "US global share",
              value: fmtPct(HEADLINE.usGlobalSharePct, 0),
            },
            {
              label: "US liters (2025)",
              value: fmtLitersM(HEADLINE.usLiters2025M),
            },
            {
              label: "EU feedstock from US",
              value: fmtPct(HEADLINE.euUsImportSharePct, 0),
            },
            {
              label: "US centers",
              value: HEADLINE.usCenters2025.toLocaleString(),
            },
          ].map((k) => (
            <div
              key={k.label}
              className="rounded-lg border border-white/10 bg-white/5 px-3 py-2"
            >
              <p className="text-[10px] font-semibold uppercase tracking-wide text-slate-400">
                {k.label}
              </p>
              <p className="mt-0.5 text-lg font-bold text-white">{k.value}</p>
            </div>
          ))}
        </div>
      </div>

      <div className="flex flex-wrap items-center gap-3">
        <ToggleGroup
          label="View"
          value={view}
          onChange={setView}
          options={[
            { id: "global", label: "Global share" },
            { id: "eu", label: "EU dependence" },
            { id: "intensity", label: "Intensity" },
            { id: "capacity", label: "Capacity" },
          ]}
        />
        {view === "global" && (
          <ToggleGroup
            label="Path"
            value={pathMetric}
            onChange={setPathMetric}
            options={[
              { id: "liters", label: "Liters" },
              { id: "share", label: "US share %" },
              { id: "centers", label: "Centers" },
            ]}
          />
        )}
        {view === "global" && (
          <ToggleGroup
            label="World line"
            value={showWorld ? "on" : "off"}
            onChange={(v) => setShowWorld(v === "on")}
            options={[
              { id: "on", label: "Show world" },
              { id: "off", label: "US only" },
            ]}
          />
        )}
        {view === "intensity" && (
          <ToggleGroup
            label="Filter"
            value={intensityFilter}
            onChange={setIntensityFilter}
            options={[
              { id: "all", label: "All" },
              { id: "EU", label: "EU + US" },
              { id: "compensated", label: "Compensated" },
              { id: "vnr", label: "VNRD only" },
            ]}
          />
        )}
      </div>

      {view === "global" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Regional share of global source plasma"
            subtitle={`Desk buckets ?? analytical HHI ${hhi.toLocaleString()} (0???10,000)`}
          >
            <div className="h-80">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={regions}
                    dataKey="value"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    innerRadius={58}
                    outerRadius={100}
                    paddingAngle={2}
                  >
                    {regions.map((_, i) => (
                      <Cell
                        key={i}
                        fill={PIE_COLORS[i % PIE_COLORS.length]}
                      />
                    ))}
                  </Pie>
                  <Tooltip
                    formatter={(v) => fmtPct(Number(v), 0)}
                    contentStyle={{ fontSize: 12 }}
                  />
                  <Legend wrapperStyle={{ fontSize: 12 }} />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="US collections vs world pool"
            subtitle="2017???2025 ?? liters and share path (estimated)"
          >
            <div className="h-80">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={path}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                  <YAxis
                    yAxisId="left"
                    tick={{ fontSize: 11 }}
                    label={{
                      value:
                        pathMetric === "centers"
                          ? "Centers"
                          : pathMetric === "share"
                            ? "Share %"
                            : "Million L",
                      angle: -90,
                      position: "insideLeft",
                      style: { fontSize: 11 },
                    }}
                  />
                  {pathMetric === "liters" && showWorld && (
                    <YAxis
                      yAxisId="right"
                      orientation="right"
                      tick={{ fontSize: 11 }}
                      hide
                    />
                  )}
                  <Tooltip contentStyle={{ fontSize: 12 }} />
                  <Legend wrapperStyle={{ fontSize: 12 }} />
                  {pathMetric === "liters" && (
                    <>
                      <Area
                        yAxisId="left"
                        type="monotone"
                        dataKey="usLitersM"
                        name="US liters (M)"
                        fill={US}
                        fillOpacity={0.25}
                        stroke={US}
                        strokeWidth={2}
                      />
                      {showWorld && (
                        <Line
                          yAxisId="left"
                          type="monotone"
                          dataKey="worldLitersM"
                          name="World liters (M)"
                          stroke={MUTED}
                          strokeWidth={2}
                          dot={false}
                        />
                      )}
                    </>
                  )}
                  {pathMetric === "share" && (
                    <Area
                      yAxisId="left"
                      type="monotone"
                      dataKey="usSharePct"
                      name="US share %"
                      fill={US}
                      fillOpacity={0.3}
                      stroke={US}
                      strokeWidth={2}
                    />
                  )}
                  {pathMetric === "centers" && (
                    <Bar
                      yAxisId="left"
                      dataKey="usCenters"
                      name="US centers"
                      fill={US}
                      radius={[4, 4, 0, 0]}
                    />
                  )}
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "eu" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Where EU PDMP plasma comes from"
            subtitle="PPTA / industry framing ?? US imports ??? EU-4 commercial bloc"
          >
            <div className="h-80">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={euOrigin}
                    dataKey="value"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    innerRadius={50}
                    outerRadius={98}
                    paddingAngle={3}
                    label={({ percent }) =>
                      `${((percent ?? 0) * 100).toFixed(0)}%`
                    }
                  >
                    <Cell fill={EU} />
                    <Cell fill={US} />
                    <Cell fill={MUTED} />
                  </Pie>
                  <Tooltip
                    formatter={(v) => fmtPct(Number(v), 0)}
                    contentStyle={{ fontSize: 12 }}
                  />
                  <Legend wrapperStyle={{ fontSize: 12 }} />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="EU structural deficit vs US cover share"
            subtitle="Liters short of Ig self-sufficiency framing ?? US cover ~38%"
          >
            <div className="h-80">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={deficit}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                  <YAxis
                    yAxisId="l"
                    tick={{ fontSize: 11 }}
                    label={{
                      value: "Deficit M L",
                      angle: -90,
                      position: "insideLeft",
                      style: { fontSize: 11 },
                    }}
                  />
                  <YAxis
                    yAxisId="r"
                    orientation="right"
                    tick={{ fontSize: 11 }}
                    domain={[0, 50]}
                    label={{
                      value: "US cover %",
                      angle: 90,
                      position: "insideRight",
                      style: { fontSize: 11 },
                    }}
                  />
                  <Tooltip contentStyle={{ fontSize: 12 }} />
                  <Legend wrapperStyle={{ fontSize: 12 }} />
                  <Area
                    yAxisId="l"
                    type="monotone"
                    dataKey="deficitML"
                    name="EU deficit (M L)"
                    fill={WARN}
                    fillOpacity={0.3}
                    stroke={WARN}
                    strokeWidth={2}
                  />
                  <Line
                    yAxisId="r"
                    type="monotone"
                    dataKey="usCoverSharePct"
                    name="US cover share %"
                    stroke={US}
                    strokeWidth={2}
                    dot={{ r: 3 }}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "intensity" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Liters collected per 1,000 residents"
            subtitle="Anchor rates ~2017???2019 ?? compensated systems pull ahead"
          >
            <div className="h-[28rem]">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={intensity} layout="vertical" margin={{ left: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis type="number" tick={{ fontSize: 11 }} />
                  <YAxis
                    type="category"
                    dataKey="name"
                    width={100}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip contentStyle={{ fontSize: 12 }} />
