                      <Area
                        yAxisId="left"
                        type="monotone"
                        dataKey="usLitersM"
                        name="US liters (M)"
                        fill={US}
                        fillOpacity={0.25}
                        stroke={US}
                        strokeWidth={2}
                      />
                      {showWorld && (
                        <Line
                          yAxisId="left"
                          type="monotone"
                          dataKey="worldLitersM"
                          name="World liters (M)"
                          stroke={MUTED}
                          strokeWidth={2}
                          dot={false}
