                  <Tooltip
                    cursor={{ strokeDasharray: "3 3" }}
                    contentStyle={{ fontSize: 12 }}
                    formatter={(v, name) => [
                      `${Number(v).toFixed(0)}%`,
                      name === "x" ? "Self-reliance" : name === "y" ? "US import" : String(name),
